// Find and Replace in both editors, the list of fonts and the vertical alignment of the
// spreadsheet toolbar. Every file is generated by code.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { p, tbl, tc, tr } from '../test/doc-layout-fixtures';
import { docx, DOC_STYLES } from './fixtures/docx';
import { expect, test } from './helpers';

const str = (ref: string, text: string) => `<c r="${ref}" t="inlineStr"><is><t>${text}</t></is></c>`;
const num = (ref: string, value: number) => `<c r="${ref}"><v>${value}</v></c>`;

/** "One": A1 "apple pie", B1 7, A2 "Apple", B3 "pear"; "Two": A1 "apple". */
const workbook = () =>
  buildXlsx({
    sheets: [
      { name: 'One', xml: worksheetXml(`<sheetData><row r="1">${str('A1', 'apple pie')}${num('B1', 7)}</row><row r="2">${str('A2', 'Apple')}</row><row r="3">${str('B3', 'pear')}</row></sheetData>`) },
      { name: 'Two', xml: worksheetXml(`<sheetData><row r="1">${str('A1', 'apple')}</row></sheetData>`) },
    ],
  });

async function mountSheet(page: Page, bytes: Uint8Array, options: { locale?: string; readOnly?: boolean } = {}): Promise<void> {
  await page.goto('/e2e/pages/editor.html');
  await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, options, 'host');
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options } },
  );
  await expect(page.locator('#host .bym-canvas')).toBeVisible();
}

const command = (page: Page, name: string) => page.locator(`#host .bym-toolbar [data-command="${name}"]`);
const bar = (page: Page) => page.locator('#host .bym-find');
const active = (page: Page) =>
  page.evaluate(() => {
    const view = (window as any).__editor.view;
    const at = view.selection.active;
    return `${view.activeSheet}:${(window as any).BymOffice.cellName(at.row, at.col)}`;
  });
const valueAt = (page: Page, sheet: number, ref: string) =>
  page.evaluate(
    ([index, where]) => {
      const api = (window as any).BymOffice;
      const at = api.parseCellRef(where);
      const found = api.getCell((window as any).__editor.view.workbook.sheets[index], at.row, at.col);
      return found ? found.value : null;
    },
    [sheet, ref] as [number, string],
  );
const modifier = process.platform === 'darwin' ? 'Meta' : 'Control';

test.describe('spreadsheet: find and replace', () => {
  test('Ctrl+F opens the bar; Enter goes from match to match round the sheet, Shift+Enter back; Escape closes it', async ({ page }) => {
    await mountSheet(page, await workbook());
    await page.evaluate(() => (window as any).__editor.view.focus());
    await page.keyboard.press(`${modifier}+f`);
    await expect(bar(page)).toBeVisible();
    await expect(page.locator('#host .bym-find-text')).toBeFocused();
    await page.keyboard.type('apple');
    await expect(page.locator('#host .bym-find-status')).toHaveText('2 matches');
    await page.keyboard.press('Enter');
    await expect.poll(() => active(page)).toBe('0:A2');
    await page.keyboard.press('Enter');
    await expect.poll(() => active(page)).toBe('0:A1');
    await page.keyboard.press('Shift+Enter');
    await expect.poll(() => active(page)).toBe('0:A2');
    // The workbook: the other sheet is shown when its cell is found.
    await page.locator('#host .bym-find-within').selectOption('workbook');
    await page.locator('#host .bym-find-text').press('Enter');
    await expect.poll(() => active(page)).toBe('1:A1');
    await page.keyboard.press('Escape');
    await expect(bar(page)).toHaveCount(0);
    await expect(page.locator('#host .bym-input')).toBeFocused();
  });

  test('the toolbar button opens the bar; Replace all is one undo step', async ({ page }) => {
    await mountSheet(page, await workbook());
    await command(page, 'find').click();
    await expect(bar(page)).toBeVisible();
    await page.locator('#host .bym-find-toggle').click();
    await page.locator('#host .bym-find-text').fill('apple');
    await page.locator('#host .bym-find-replacement').fill('plum');
    await page.locator('#host .bym-find-replace-all').click();
    await expect(page.locator('#host .bym-find-status')).toHaveText('2 replacements');
    expect(await valueAt(page, 0, 'A1')).toBe('plum pie');
    expect(await valueAt(page, 0, 'A2')).toBe('plum');
    expect(await valueAt(page, 1, 'A1')).toBe('apple');
    await page.evaluate(() => (window as any).__editor.view.undo());
    expect(await valueAt(page, 0, 'A1')).toBe('apple pie');
    expect(await valueAt(page, 0, 'A2')).toBe('Apple');
  });

  test('Replace all is not given up because a calculation goes on writing its results meanwhile', async ({ page }) => {
    // 20,000 text cells to go through (several slices) and a long chain of formulas that is calculated anew in slices.
    let rows = '';
    for (let r = 1; r <= 20000; r++) rows += `<row r="${r}">${str(`A${r}`, `item ${r}`)}${r === 1 ? num('B1', 1) : `<c r="B${r}"><f>B${r - 1}+1</f><v>${r}</v></c>`}</row>`;
    await mountSheet(page, await buildXlsx({ sheets: [{ name: 'Big', xml: worksheetXml(`<sheetData>${rows}</sheetData>`) }] }));
    const result = await page.evaluate(async () => {
      const view = (window as any).__editor.view;
      // Changes the start of the chain: every formula after it is calculated again, slice after slice.
      view.setCellInput(0, 1, '5');
      return view.replaceAll('item', 'thing');
    });
    expect(result).toEqual({ replaced: 20000, cells: 20000, skipped: 0 });
    expect(await valueAt(page, 0, 'A20000')).toBe('thing 20000');
  });

  test('read-only: finding works, replacing is not offered', async ({ page }) => {
    await mountSheet(page, await workbook(), { readOnly: true });
    await expect(command(page, 'find')).toBeEnabled();
    await command(page, 'find').click();
    await page.locator('#host .bym-find-toggle').click();
    await expect(page.locator('#host .bym-find-replace')).toBeDisabled();
    await expect(page.locator('#host .bym-find-replace-all')).toBeDisabled();
    await page.locator('#host .bym-find-text').fill('pear');
    await page.locator('#host .bym-find-text').press('Enter');
    await expect.poll(() => active(page)).toBe('0:B3');
  });

  test('the bar speaks Turkish, and folds Turkish letters', async ({ page }) => {
    await mountSheet(page, await workbook(), { locale: 'tr' });
    await command(page, 'find').click();
    await expect(bar(page)).toHaveAttribute('aria-label', 'Bul ve değiştir');
    await page.locator('#host .bym-find-text').fill('APPLE');
    await expect(page.locator('#host .bym-find-status')).toHaveText('2 sonuç');
  });
});

test.describe('spreadsheet toolbar: font and vertical alignment', () => {
  test('the list of fonts shows the font of the cell and sets the font of the selection', async ({ page }) => {
    await mountSheet(page, await workbook());
    const list = page.locator('#host .bym-tb-font');
    await expect(list).toHaveAttribute('aria-label', 'Font');
    await expect(list).toHaveValue('Calibri');
    await list.selectOption('Georgia');
    const name = await page.evaluate(() => {
      const view = (window as any).__editor.view;
      return view.selectionFormat.font.name;
    });
    expect(name).toBe('Georgia');
    await page.evaluate(() => (window as any).__editor.view.undo());
    await expect(list).toHaveValue('Calibri');
  });

  test('top, middle and bottom work like radio buttons; a cell without one is at the bottom', async ({ page }) => {
    await mountSheet(page, await workbook());
    await expect(command(page, 'alignBottom')).toHaveAttribute('aria-pressed', 'true');
    await command(page, 'alignTop').click();
    await expect(command(page, 'alignTop')).toHaveAttribute('aria-pressed', 'true');
    await expect(command(page, 'alignBottom')).toHaveAttribute('aria-pressed', 'false');
    expect(await page.evaluate(() => (window as any).__editor.view.selectionFormat.alignment.vertical)).toBe('top');
    await command(page, 'alignMiddle').click();
    expect(await page.evaluate(() => (window as any).__editor.view.selectionFormat.alignment.vertical)).toBe('center');
    // Pressing the one that is on goes back to the bottom.
    await command(page, 'alignMiddle').click();
    expect(await page.evaluate(() => (window as any).__editor.view.selectionFormat.alignment.vertical ?? null)).toBe(null);
    await expect(command(page, 'alignBottom')).toHaveAttribute('aria-pressed', 'true');
  });
});

// ------------------------------------------------------------------ documents

async function mountDoc(page: Page, bytes: Uint8Array, options: { readOnly?: boolean; locale?: string } = {}): Promise<void> {
  await page.goto('/e2e/pages/doc-edit.html');
  await expect(page.locator('#state')).toHaveText('ready');
  await page.evaluate(([input, opts]) => (window as any).__mountEdit(input, opts), [Array.from(bytes), options] as [number[], typeof options]);
  await page.waitForFunction(() => (window as any).__view.layoutDone === true, undefined, { timeout: 120_000 });
}

const STYLES = DOC_STYLES + '<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/></w:style>';
const document = () => docx(p('The cat sat.') + tbl(tr(tc('a cat') + tc('dog')), [3000, 3000]) + p('Cat and cat.'), { styles: STYLES });
const selected = (page: Page) => page.evaluate(() => (window as any).__view.getSelectedText());
const docText = (page: Page) => page.evaluate(() => (window as any).BymOffice.documentText((window as any).__view.document) as string);

test.describe('document: find and replace', () => {
  test('Ctrl+F finds in the body and in tables; Replace takes the match and goes on; Replace all is one undo step', async ({ page }) => {
    await mountDoc(page, await document());
    await page.locator('#host .bym-doc-input').focus();
    await page.keyboard.press(`${modifier}+f`);
    await expect(bar(page)).toBeVisible();
    await page.keyboard.type('cat');
    await expect(page.locator('#host .bym-find-status')).toHaveText('4 matches');
    await page.keyboard.press('Enter');
    await expect.poll(() => selected(page)).toBe('cat');
    expect(await page.evaluate(() => (window as any).__view.getSelection().anchor.path)).toEqual([0]);
    await page.keyboard.press('Enter');
    expect(await page.evaluate(() => (window as any).__view.getSelection().anchor.path)).toEqual([1, 0, 0, 0]);
    await page.locator('#host .bym-find-toggle').click();
    await page.locator('#host .bym-find-replacement').fill('bird');
    await page.locator('#host .bym-find-replace').click();
    await expect.poll(() => docText(page)).toContain('a bird');
    await page.locator('#host .bym-find-replace-all').click();
    await expect(page.locator('#host .bym-find-status')).toHaveText('3 replacements');
    expect(await docText(page)).not.toMatch(/cat/i);
    await page.evaluate(() => (window as any).__view.undo());
    expect(await docText(page)).toContain('Cat and cat.');
    expect(await docText(page)).toContain('a bird');
  });

  test('Find opens with the selected text; the toolbar has the button at its end', async ({ page }) => {
    await mountDoc(page, await document());
    await page.evaluate(() => (window as any).__view.setSelection({ anchor: { story: 'body', path: [0], offset: 4 }, focus: { story: 'body', path: [0], offset: 7 } }));
    await page.locator('#host .bym-doc-toolbar [data-command="find"]').click();
    await expect(page.locator('#host .bym-find-text')).toHaveValue('cat');
  });
});
